public void startListener(Listener listener, String region, List<Rule> rules) {
    startListener(listener, region, rules, null);
}

/**
 * Starts a listener using an already-resolved load balancer, avoiding a call back into
 * ElbV2Service (needed while ElbV2Service itself is being initialized).
 */
public void startListener(Listener listener, String region, List<Rule> rules, LoadBalancer resolvedLoadBalancer) {
    if (config.services().elbv2().mock()) {
        return;
    }
    String listenerArn = listener.getListenerArn();
    List<CompiledRule> compiled = compileRules(rules);
    ruleChains.put(listenerArn, new AtomicReference<>(compiled));
    listenerRegions.put(listenerArn, region);
    ListenerBinding binding;
    if (resolvedLoadBalancer != null) {
        binding = new ListenerBinding(listener.getPort(), normalizeHost(resolvedLoadBalancer.getDnsName()));
    } else {
        binding = binding(listener, region);
    }

